</template>

<script>
export default {
	data() {
		return {
			loading: true,
			status: 'loadmore',
			is_update: false,
			has_more: false,
			current: 0,
			scrollTop: 0,
			statusBarHeight: uni.getSystemInfoSync().statusBarHeight || 20,
			swiperCurrent: 0,
			hots: [],
			recommends: []
		};
	},
	onShow() {
		this.getGoodsIndex();
	},
	computed: {
		headerStyle() {
			return {
				paddingTop: this.statusBarHeight + 'px',
				backgroundColor: (this.theme && this.theme.bgColor) || '#374486'
			};
		},
		swiperList() {
			return this.vuex_config.swiper || [];
		},
		noticeItems() {
			return this.vuex_config.notice || [];
		},
		navigatePages() {
			const items = this.vuex_config.navigate || [];
			const pages = [];
			for (let index = 0; index < items.length; index += 9) {
				pages.push(items.slice(index, index + 9));
			}
			return pages;
		},
		navigateHeight() {
			const count = (this.vuex_config.navigate || []).length;
			return count > 6 ? 510 : count > 3 ? 350 : 190;
		},
		tabbarList() {
			return this.vuex_config.tabbar && this.vuex_config.tabbar.isshow ? (this.vuex_config.tabbar.list || []) : [];
		}
	},
	methods: {
		swiperChange(e) {
			this.swiperCurrent = e.detail.current;
		},
		change(e) {
			this.current = e.detail.current;
		},
		grids(e) {
			let path = e.path;
			if (path == '/' || !path) {
				return;
			}
			if (path.substr(0, 1) == 'p') {
				path = '/' + path;
			}
			if (path.includes('http')) {
				this.$u.vuex('vuex_webs', {
					path: e.path,
					title: e.name
				});
				this.$u.route('/pages/webview/webview');
				return;
			}
			this.$u.route(path);
		},
		openPage(index) {
			if (!this.swiperList[index]) return;
			this.grids({
				path: this.swiperList[index].url,
				name: this.swiperList[index].title
			});
		},
		switchTabbar(item) {
			if (!item || !item.path || item.path === '/pages/index/index' || item.path === 'pages/index/index') return;
			if (item.path.indexOf('http') === 0) {
				this.grids({ path: item.path, name: item.text });
				return;
			}
			const url = item.path.substr(0, 1) === '/' ? item.path : '/' + item.path;
			this.$u.route({ type: 'redirectTo', url });
		},
		click(index) {
			if (this.vuex_config.notice) {
				let url = this.vuex_config.notice[index].path;
				if (url) {
					this.grids({
						path: url,
						name: this.vuex_config.notice[index].title
					});
				}
			}
		},
		getGoodsIndex() {
			this.$api.getGoodsIndex().then(({code,data:res,msg}) => {
				if (code) {
					this.hots = res.hots;
					this.recommends = res.recommends;
				}
			});
		}
	},
	onPageScroll(e) {
		this.scrollTop = e.scrollTop;
	},
	//下拉刷新
	onPullDownRefresh() {},
	onReachBottom() {}
};
</script>

